import { NextResponse, type NextRequest } from 'next/server';

const BAHASA = ['id', 'en'];

export function middleware(req: NextRequest) {
  const { pathname } = req.nextUrl;
  if (BAHASA.some((b) => pathname.startsWith(`/${b}`))) return NextResponse.next();
  const pilihan = req.headers.get('accept-language')?.startsWith('en') ? 'en' : 'id';
  return NextResponse.redirect(new URL(`/${pilihan}${pathname}`, req.url));
}

